import{_ as a,a as t,c as i,ac as h}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse(`{"title":"第一册：英语初阶 · Lesson 62 What's the matter with them?","description":"学习 have 表身体状况与 must，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 62 What's the matter with them?","description":"学习 have 表身体状况与 must，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 have 表身体状况与 must，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 61 A bad cold","link":"/life/english/new-concept/book-1/unit-03/lesson-061"},"next":{"text":"第一册：英语初阶 · Lesson 63 Thank you, doctor.","link":"/life/english/new-concept/book-1/unit-03/lesson-063"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 61 A bad cold","link":"/life/english/new-concept/book-1/unit-03/lesson-061"},"next":{"text":"第一册：英语初阶 · Lesson 63 Thank you, doctor.","link":"/life/english/new-concept/book-1/unit-03/lesson-063"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-03/lesson-062.md","filePath":"life/english/new-concept/book-1/unit-03/lesson-062.md"}`),n={name:"life/english/new-concept/book-1/unit-03/lesson-062.md"};function o(s,e,l,r,d,c){return t(),i("div",null,[...e[0]||(e[0]=[h('<h1 id="第一册-英语初阶-·-lesson-62-what-s-the-matter-with-them" tabindex="-1">第一册：英语初阶 · Lesson 62 What&#39;s the matter with them? <a class="header-anchor" href="#第一册-英语初阶-·-lesson-62-what-s-the-matter-with-them" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 62 What&#39;s the matter with them?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-03/overview">单元 3</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-061">配套课 Lesson 61</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>描述身体不适并理解必要事项 本课要掌握have 表身体状况与 must，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>headache</td><td>/ˈhedeɪk/</td><td>n.</td><td>头痛</td><td>have a headache</td></tr><tr><td>ill</td><td>/ɪl/</td><td>adj.</td><td>生病的</td><td>be ill</td></tr><tr><td>feel</td><td>/fiːl/</td><td>v.</td><td>感到</td><td>feel tired</td></tr><tr><td>appointment</td><td>/əˈpɔɪntmənt/</td><td>n.</td><td>预约</td><td>make an appointment</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>have a headache — have 加名词</li><li>feel tired — feel 加形容词</li></ul><h2 id="语法讲解-have-表身体状况与-must" tabindex="-1">语法讲解：have 表身体状况与 must <a class="header-anchor" href="#语法讲解-have-表身体状况与-must" aria-label="Permalink to &quot;语法讲解：have 表身体状况与 must&quot;">​</a></h2><p>have 可表达某些身体状况，如 have a headache；be 与形容词搭配，如 be tired。must + 原形可表达强烈要求，但本页只是语言练习，不提供诊断或治疗建议。询问状况可用 What is the matter with ...?，with 后用宾格。第三人称肯定 have 变 has，疑问用 does ... have。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>What is the matter with him?</p></blockquote><p>他怎么了？</p><p>What is the matter 构成询问状况的固定问句；with him 指明对象，him 是介词后的宾格。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>不要把 has a headache 写成 is a headache；with 后用 him 而非 he。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“What is the matter with him?”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>What is the matter with him? Mina has a headache today.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“描述身体不适并理解必要事项”写两至三句，再读给同伴听。至少使用一次have 表身体状况与 must，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>What is the matter 构成询问状况的固定问句；with him 指明对象，him 是介词后的宾格。 Mina 是第三人称单数，have 变 has；a headache 是表示身体状况的名词短语，today 表时间。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选择 he/him：What is the matter with ___?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> him</p><p><strong>解析：</strong> 按本课规则判断：have 可表达某些身体状况，如 have a headache；be 与形容词搭配，如 be tired。must + 原形可表达强烈要求，但本页只是语言练习，不提供诊断或治疗建议。询问状况可用 What is the matter with ...?，with 后用宾格。第三人称肯定 have 变 has，疑问用 does ... have。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“他怎么了？”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> What is the matter with him?</p><p><strong>解析：</strong> What is the matter 构成询问状况的固定问句；with him 指明对象，him 是介词后的宾格。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：Mina has a headache today.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 米娜今天头痛。</p><p><strong>解析：</strong> Mina 是第三人称单数，have 变 has；a headache 是表示身体状况的名词短语，today 表时间。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：have 表身体状况与 must。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-061">上一课</a> · <a href="/life/english/new-concept/book-1/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-063">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const u=a(n,[["render",o]]);export{m as __pageData,u as default};
